if (typeof window !== 'undefined') { preClick = new Audio('/sounds/click.mp3'); preClick.preload = 'auto'; preClick.volume = 0.7; prePop = new Audio('/pop.mp3'); prePop.preload = 'auto'; prePop.volume = 0.7; preSpark = new Audio('/sounds/spark.mp3'); preSpark.preload = 'auto'; preSpark.volume = 0.6; preCoin = new Audio('/sounds/points.mp3'); preCoin.preload = 'auto'; preCoin.volume = 0.5; preGoldCoin = new Audio('/sounds/gold-coin.mp3'); preGoldCoin.preload = 'auto'; preGoldCoin.volume = 0.6; preSkullReport = new Audio('/sounds/skull-report.mp3'); preSkullReport.preload = 'auto'; preSkullReport.volume = 0.5; preloadBuffer('click', '/sounds/click.mp3'); preloadBuffer('pop', '/pop.mp3'); preloadBuffer('spark', '/sounds/spark.mp3'); preloadBuffer('coin', '/sounds/points.mp3'); preloadBuffer('goldCoin', '/sounds/gold-coin.mp3'); preloadBuffer('skullReport', '/sounds/skull-report.mp3') }
