function useDragScroll() { var ref = useRef<HTMLDivElement>(null); var isDragging = useRef(false); var startX = useRef(0); var scrollLeft = useRef(0); var moved = useRef(false); function onMouseDown(e: React.MouseEvent) { if (!ref.current) return; isDragging.current = true; moved.current = false; startX.current = e.pageX - ref.current.offsetLeft; scrollLeft.current = ref.current.scrollLeft; ref.current.style.cursor = 'grabbing'; ref.current.style.userSelect = 'none' }; useEffect(function () { function onMouseMove(e: MouseEvent) { if (!isDragging.current || !ref.current) return; e.preventDefault(); var x = e.pageX - ref.current.offsetLeft; var walk = (x - startX.current) * 1.5; if (Math.abs(walk) > 3) moved.current = true; ref.current.scrollLeft = scrollLeft.current - walk } function onMouseUp() { isDragging.current = false; if (ref.current) { ref.current.style.cursor = 'grab'; ref.current.style.userSelect = '' } } window.addEventListener('mousemove', onMouseMove); window.addEventListener('mouseup', onMouseUp); return function () { window.removeEventListener('mousemove', onMouseMove); window.removeEventListener('mouseup', onMouseUp) } }, []); return { ref: ref, onMouseDown: onMouseDown, wasDragged: function () { return moved.current } } }

